WITH gated AS (SELECT model FROM llm_gateway.usage_log WHERE {{ time_filter('timestamp') }} AND model != '' GROUP BY model HAVING count() >= 100) SELECT rule AS "Rule", count() AS "Occurrences" FROM (SELECT arrayJoin(guard_rules) AS rule FROM llm_gateway.request_signals WHERE {{ time_filter('timestamp') }} AND model IN (SELECT model FROM gated)) GROUP BY rule ORDER BY "Occurrences" DESC LIMIT 15